func newSubscriptionsPreviewUpdateCmd(c *client.Client, opts *output.Options) *cobra.Command {
	cmd := &cobra.Command{
		Use:     "preview-update <subscription_id>",
		Short:   "Preview an update to a subscription",
		Long:    "Preview an update to a subscription" + "\n\nBody schema:\n" + schema.RenderTree(subscriptionsPreviewUpdateBodySchema, style.Profile{}) + "\nPass these fields as JSON with --json. Run with --schema for the full JSON Schema.",
		Example: "  paddle subscriptions preview-update <subscription_id> --json '{\"address_id\":\"...\"}'\n  paddle subscriptions preview-update <subscription_id> --json @subscription.json\n  some-command | paddle subscriptions preview-update <subscription_id> --json -",
		Args:    cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if ok, _ := cmd.Flags().GetBool("schema"); ok {
				return schema.PrintRaw(opts.Writer, subscriptionsPreviewUpdateBodySchema, opts.Compact)
			}
			path := "/subscriptions/{subscription_id}/preview"
			path = strings.Replace(path, "{"+"subscription_id"+"}", args[0], 1)

			qp := make(map[string]string)

			body := make(map[string]interface{})

			jsonInput, _ := cmd.Flags().GetString("json")
			if jsonInput != "" {
				raw, err := readJSONInput(jsonInput)
				if err != nil {
					return err
				}
				if err := json.Unmarshal(raw, &body); err != nil {
					return fmt.Errorf("invalid JSON input: %w", err)
				}
			}

			var bodyBytes []byte
			if len(body) > 0 {
				var err error
				bodyBytes, err = json.Marshal(body)
				if err != nil {
					return fmt.Errorf("encoding request body: %w", err)
				}
			}

			resp, err := c.Do("PATCH", path, qp, bodyBytes)
			if err != nil {
				return err
			}

			if resp.StatusCode >= 400 {
				return client.ParseAPIError(resp)
			}

			hasMore, cursor := output.ParsePagination(resp.Body)
			if hasMore {
				opts.NextCommand = output.SynthesizeNextCommand(cmd, cursor)
			} else {
				opts.NextCommand = ""
			}
			columns := subscriptionsPreviewUpdateColumns()
			return output.Print(resp.Body, columns, *opts)
		},
	}

	cmd.Flags().String("json", "", "Request body as JSON: inline ('{…}'), from a file (@body.json), or from stdin (-)")
	cmd.Flags().Bool("schema", false, "Print the request body JSON schema and exit")

	return cmd
}

func subscriptionsPreviewUpdateColumns() []output.ColumnDef {
	return nil
}

