func newSubscriptionsResumeCmd(c *client.Client, opts *output.Options) *cobra.Command {
	cmd := &cobra.Command{
		Use:     "resume <subscription_id>",
		Short:   "Resume a paused subscription",
		Long:    "Resume a paused subscription" + "\n\nBody schema:\n" + schema.RenderTree(subscriptionsResumeBodySchema, style.Profile{}) + "\nPass these fields as JSON with --json. Run with --schema for the full JSON Schema.",
		Example: "  paddle subscriptions resume <subscription_id> --json '{\"effective_from\":\"2024-01-01T00:00:00Z\"}'\n  paddle subscriptions resume <subscription_id> --json @subscription.json\n  some-command | paddle subscriptions resume <subscription_id> --json -",
		Args:    cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if ok, _ := cmd.Flags().GetBool("schema"); ok {
				return schema.PrintRaw(opts.Writer, subscriptionsResumeBodySchema, opts.Compact)
			}
			path := "/subscriptions/{subscription_id}/resume"
			path = strings.Replace(path, "{"+"subscription_id"+"}", args[0], 1)

			qp := make(map[string]string)

			body := make(map[string]interface{})

			jsonInput, _ := cmd.Flags().GetString("json")
			if jsonInput != "" {
				raw, err := readJSONInput(jsonInput)
				if err != nil {
					return err
				}
				if err := json.Unmarshal(raw, &body); err != nil {
					return fmt.Errorf("invalid JSON input: %w", err)
				}
			}

			var bodyBytes []byte
			if len(body) > 0 {
				var err error
				bodyBytes, err = json.Marshal(body)
				if err != nil {
					return fmt.Errorf("encoding request body: %w", err)
				}
			}

			resp, err := c.Do("POST", path, qp, bodyBytes)
			if err != nil {
				return err
			}

			if resp.StatusCode >= 400 {
				return client.ParseAPIError(resp)
			}

			hasMore, cursor := output.ParsePagination(resp.Body)
			if hasMore {
				opts.NextCommand = output.SynthesizeNextCommand(cmd, cursor)
			} else {
				opts.NextCommand = ""
			}
			columns := subscriptionsResumeColumns()
			return output.Print(resp.Body, columns, *opts)
		},
	}

	cmd.Flags().String("json", "", "Request body as JSON: inline ('{…}'), from a file (@body.json), or from stdin (-)")
	cmd.Flags().Bool("schema", false, "Print the request body JSON schema and exit")

	return cmd
}

func subscriptionsResumeColumns() []output.ColumnDef {
	return nil
}

const subscriptionsResumeBodySchema = "{\"oneOf\":[{\"properties\":{\"effective_from\":{\"description\":\"RFC 3339 datetime string.\",\"format\":\"date-time\",\"type\":\"string\"},\"on_resume\":{\"description\":\"How Paddle should set the billing period for the subscription when resuming. If omitted, defaults to `start_new_billing_period`.\",\"enum\":[\"continue_existing_billing_period\",\"start_new_billing_period\"],\"type\":\"string\"}},\"required\":[\"effective_from\"],\"type\":\"object\"},{\"properties\":{\"effective_from\":{\"anyOf\":[{\"enum\":[\"immediately\"],\"type\":\"string\"},{\"type\":\"null\"}],\"default\":\"immediately\",\"description\":\"When this subscription change should take effect from. You can pass `immediately` to resume immediately.\\n\\nValid where subscriptions have the status of `paused`.\\n\\nDefaults to `immediately` if omitted.\"},\"on_resume\":{\"description\":\"How Paddle should set the billing period for the subscription when resuming. If omitted, defaults to `start_new_billing_period`.\",\"enum\":[\"continue_existing_billing_period\",\"start_new_billing_period\"],\"type\":\"string\"}},\"required\":[\"effective_from\"],\"type\":\"object\"},{\"type\":\"null\"},{\"additionalProperties\":false,\"type\":\"object\"}]}"
